export function temple(id: string): Temple | undefined {
  return temples.find((t) => t.id === id);
}
export function pandit(id: string): Pandit | undefined {
  return pandits.find((p) => p.id === id);
}
/** Devanagari name in Hindi mode, falling back to the English name for
 *  pandits that don't have one yet (nameHi is optional on the data). */
export function panditDisplayName(p: Pandit, lang: "en" | "hi"): string {
  return lang === "hi" && p.nameHi ? p.nameHi : p.name;
}
export function service(id: string): Service | undefined {
  return services.find((s) => s.id === id);
}
export function serviceName(id: string): string {
  return service(id)?.name || id;
}
export function panditsAtTemple(templeId: string): Pandit[] {
  return pandits.filter((p) => p.temples.includes(templeId));
}
export function panditsForService(svcId: string): Pandit[] {
  return pandits.filter((p) => p.services.includes(svcId));
}
export function templesForService(svcId: string): Temple[] {
  return temples.filter((t) => t.services.includes(svcId));
}
